import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

import openapiTS, { astToString } from 'openapi-typescript';
import { format, resolveConfig } from 'prettier';
import { expect, it } from 'vitest';

const SPEC = new URL('../../../../api/openapi.json', import.meta.url);
const GENERATED = fileURLToPath(new URL('../schema.gen.ts', import.meta.url));
const HEADER =
  '/**\n * This file was auto-generated by openapi-typescript.\n * Do not make direct changes to the file.\n */\n\n';

/** What `api:types` writes for `spec`: openapi-typescript, then Prettier with the repo config. */
async function generate(spec: URL | Record<string, unknown>): Promise<string> {
  const fresh = HEADER + astToString(await openapiTS(spec as Parameters<typeof openapiTS>[0]));
  return format(fresh, { ...(await resolveConfig(GENERATED)), filepath: GENERATED });
}

/** The committed types match apps/api/openapi.json; else run `pnpm --filter @cityturfer/web run api:types`. */
it('schema.gen.ts is generated from the current apps/api/openapi.json', async () => {
  expect(
    (await generate(SPEC)) === (await readFile(GENERATED, 'utf8')),
    'run: pnpm --filter @cityturfer/web run api:types'
  ).toBe(true);
}, 30_000);

/** Negative control: a spec that drifted (one path dropped, in memory only) no longer matches. */
it('detects drift: a changed spec does not match schema.gen.ts', async () => {
  const spec = JSON.parse(await readFile(SPEC, 'utf8')) as { paths: Record<string, unknown> };
  const [first] = Object.keys(spec.paths);
  expect(first).toBeDefined();
  delete spec.paths[first!];
  expect((await generate(spec)) === (await readFile(GENERATED, 'utf8'))).toBe(false);
}, 30_000);
